const forecasts={5:{curve:'M600 69Q750 55 900 42',band:'M600 69Q740 28 900 8L900 100Q740 91 600 69',label:'5-minute'},15:{curve:'M600 69Q750 50 900 55',band:'M600 69Q740 10 900 2L900 135Q740 109 600 69',label:'15-minute'},60:{curve:'M600 69Q750 65 900 80',band:'M600 69Q740 5 900 0L900 195Q740 145 600 69',label:'1-hour'}};
document.querySelectorAll('[data-horizon]').forEach(button=>button.addEventListener('click',()=>{const chosen=forecasts[button.dataset.horizon];document.querySelectorAll('[data-horizon]').forEach(item=>{const active=item===button;item.classList.toggle('active',active);item.setAttribute('aria-pressed',String(active));});document.getElementById('forecast-path').setAttribute('d',chosen.curve);document.getElementById('band-path').setAttribute('d',chosen.band);document.getElementById('horizon-note').textContent=`Illustrative ${chosen.label} horizon. Uncertainty grows with time.`;}));

const outcomeStage=document.getElementById('prediction-reality');
if(outcomeStage){
  const view={rows:[],shown:0,visible:false,timer:null},escape=value=>String(value).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const price=value=>{const n=Number(value);return Number.isFinite(n)?new Intl.NumberFormat('en-US',{maximumFractionDigits:n<1?8:n<100?5:2}).format(n):'—';};
  const windowText=seconds=>{const n=Number(seconds)||0;return n>=3600?`${Math.round(n/360)/10}h`:n>=60?`${Math.round(n/6)/10}m`:`${n}s`;};
  const row=value=>{const correct=Number(value.directionCorrect)===1,move=Number(value.actualMovePercent),verified=Number(value.verifiedAtMs||value.targetAtMs);return `<tr class="outcome-enter"><td><span class="market-glyph">◇</span>${escape(value.market||'—')}</td><td>${escape(windowText(value.horizonSeconds))}</td><td>${escape(price(value.predictedPrice))}</td><td>${escape(price(value.actualPrice))}</td><td class="${move>=0?'outcome-positive':'outcome-negative'}">${Number.isFinite(move)?`${move>=0?'+':''}${move.toFixed(3)}%`:'—'}</td><td><span class="outcome-direction ${correct?'correct':'miss'}">${correct?'✓ MATCH':'↯ MISS'}</span></td><td>${verified?escape(new Date(verified).toLocaleString([],{month:'short',day:'2-digit',hour:'2-digit',minute:'2-digit'})):'—'}</td></tr>`;};
  const reveal=()=>{if(!view.visible||view.shown>=view.rows.length)return;const body=document.getElementById('outcome-rows');body.insertAdjacentHTML('beforeend',row(view.rows[view.shown++]));const latest=body.lastElementChild;latest.classList.add('outcome-latest');const scroll=document.querySelector('.outcome-scroll');scroll.scrollTo({top:scroll.scrollHeight,behavior:'smooth'});document.getElementById('outcome-live-label').textContent='LIVE SHADOW · NEW ACTUALIZED OUTCOME';setTimeout(()=>latest.classList.remove('outcome-latest'),1500);};
  const schedule=()=>{clearInterval(view.timer);if(view.visible&&view.shown<view.rows.length)view.timer=setInterval(reveal,2000);};
  fetch('/api/oracle961/outcomes').then(response=>{if(!response.ok)throw new Error('feed unavailable');return response.json();}).then(feed=>{view.rows=Array.isArray(feed.rows)?feed.rows:[];view.shown=Math.min(20,view.rows.length);document.getElementById('outcome-rows').innerHTML=view.rows.slice(0,view.shown).map(row).join('')||'<tr class="outcome-placeholder"><td colspan="7">No actualized predictions are available yet.</td></tr>';document.getElementById('outcome-round').textContent=feed.generatedAtMs?`Round ${new Date(feed.generatedAtMs).toLocaleString()}`:'Hourly round';document.getElementById('outcome-live-label').textContent=view.rows.length?'LIVE SHADOW · VERIFIED OUTCOMES':'WAITING FOR ACTUALIZED OUTCOMES';schedule();}).catch(()=>{document.getElementById('outcome-rows').innerHTML='<tr class="outcome-placeholder"><td colspan="7">The verified outcome feed is between hourly publications.</td></tr>';document.getElementById('outcome-live-label').textContent='HOURLY FEED TEMPORARILY UNAVAILABLE';});
  new IntersectionObserver(entries=>{view.visible=entries[0].isIntersecting;schedule();},{threshold:.18}).observe(outcomeStage);let frame=0;addEventListener('scroll',()=>{if(frame)return;frame=requestAnimationFrame(()=>{frame=0;const box=outcomeStage.getBoundingClientRect(),offset=Math.max(-28,Math.min(28,(innerHeight/2-(box.top+box.height/2))*.045));outcomeStage.style.setProperty('--outcome-parallax',`${offset}px`);});},{passive:true});
}
